 browser=await chromium.launch({executablePath:process.env.PK_CHROME||'/usr/bin/google-chrome',headless:true,args:['--no-sandbox','--enable-gpu','--use-gl=angle','--use-angle=gl','--ozone-platform=x11','--ignore-gpu-blocklist','--disable-background-networking']});context=await browser.newContext({viewport:report.viewport,recordVideo:{dir:path.join(scratch,'video'),size:report.viewport}});await context.route('**/*',r=>{const u=new URL(r.request().url());if(u.origin!==new URL(base).origin){report.external.push(u.origin);return r.abort();}return r.continue();});page=await context.newPage();video=page.video();page.on('pageerror',e=>report.errors.push(e.message));await page.goto(base,{waitUntil:'networkidle'});await page.waitForSelector('.living-ready');note('Pełny rdzeń i aktualny katalog');await page.waitForTimeout(1000);
